/* Real Codex bridge. No credentials in the browser. No simulated fallback. */
const aiBase='http://127.0.0.1:59319',aiPreviousAct=act,aiPreviousLoading=loading,aiPreviousBrief=simpleBrief,aiPreviousDirty=dirty;
let aiController=null,aiToken='',aiPending=null;
async function aiRequest(payload){aiController=new AbortController();const status=await fetch(aiBase+'/status',{signal:aiController.signal});if(!status.ok)throw Error('本机Codex服务未就绪');aiToken=(await status.json()).token;const response=await fetch(aiBase+'/run',{method:'POST',headers:{'Content-Type':'application/json','X-Menu-Token':aiToken},body:JSON.stringify(payload),signal:aiController.signal});let body;try{body=await response.json()}catch{throw Error('本机Codex服务返回了无效响应')}if(!response.ok)throw Error(body.error||'Codex调用失败');if(!body.result||!body.completedAt)throw Error('Codex未返回完整结果');return body;}
function aiPayload(kind){const r=Ref.ensure(s);return {kind,consent:true,width:Number(s.width),height:Number(s.height),image:r.source==='upload'?r.image:'',brief:JSON.stringify({template:r.source==='gallery'?r.name:undefined,analysis:r.analysis?.kind==='codex'?r.analysis.result:undefined,productCount:M.items(s).length,products:kind==='generate'?M.items(s).map(x=>({nameLength:x.name.length,hasPhoto:!!x.image,hasDemoArt:!!x.art})):undefined,brandColors:M.ensureBrand(s),requirements:s.intentNotes||'',language:s.language})};}
function aiConfirm(kind){const payload=aiPayload(kind);const brand=JSON.parse(payload.brief);delete brand.brandColors.decorImage;delete brand.brandColors.decorName;payload.brief=JSON.stringify(brand);aiPending={kind,payload,target:s,revision:s.revision};modal(kind==='analyze'?'使用 Codex 分析参考图':'使用 Codex 生成菜单',`<p>将通过本机已登录的 Codex，把以下资料发送至 OpenAI：</p><ul><li>${payload.image?'当前上传的参考图片':'所选原创模板名称（不发送商品图片）'}</li><li>画布尺寸、商品数量${kind==='generate'?'、名称长度及图片有无':''}、品牌配色、语言和补充设计要求</li></ul><p>不额外发送商品表中的名称、价格、图片或品牌Logo，不读取或复制登录凭据。参考图中可见的文字、价格和标志会随整张图发送，请确认你有权使用。调用会使用当前账户额度，可能需要约 1–3 分钟。</p><p class="hint">AI负责风格与布局建议，程序准确绑定商品资料；不是逐像素复刻。调用失败会明确报错，不回退为模拟结果。</p>`,btn('取消','ai-dismiss')+btn('同意发送并开始','ai-start','','primary'));}
function aiValidateClient(v){if(!v||!Array.isArray(v.slots)||v.slots.length!==v.capacity||v.capacity<1||v.capacity>6)throw Error('AI布局数据无效');for(const k of ['bg','ink','accent','card','muted','line'])if(!/^#[\da-f]{6}$/i.test(v.palette?.[k]))throw Error('AI配色数据无效');for(const b of v.slots)if(!['x','y','w','h'].every(k=>Number.isFinite(b[k]))||b.x<0||b.y<0||b.w<.2||b.h<.18||b.x+b.w>1.001||b.y+b.h>1.001)throw Error('AI坐标无效');return v;}
async function aiRun(request){const {kind,payload,target,revision}=request;if(s!==target||s.revision!==revision){error='设计条件已变化，请重新发起AI任务。';render();return;}if(kind==='generate'&&simpleBlockers().length){error=simpleBlockers().join('；');render();return;}const token=++job;error='';busy={type:kind==='analyze'?'codex-analysis':'codex-generate',progress:0};if(kind==='analyze'){Ref.ensure(s).analysis={status:'running',kind:'codex'};save();}render();try{const response=await aiRequest(payload);if(token!==job||s!==target)return;const design=aiValidateClient(response.result);checkpoint();if(kind==='analyze'){dirty(true);const r=Ref.ensure(s);r.recipe=design.recipe;r.palette='nature';r.analysis={status:'ready',kind:'codex',result:design,completedAt:response.completedAt};r.interpreted=false;s.density=design.capacity;}else{const previous=s.generated?structuredClone(s):null;if(previous)delete previous.previousDesign;const r=Ref.ensure(s);r.recipe=design.recipe;r.interpreted=true;r.samples=true;r.confirmed=true;s.aiDesign=design;s.aiGeneratedAt=response.completedAt;s.layout=design.recipe;s.style='nature';s.fontMood=/宋|(?<!无)衬线/.test(design.typography)?'serif':'sans';s.compositionVariant=0;s.density=design.capacity;s.generated=true;s.maxStep=8;s.step=7;s.page=0;s.pageOrder=[];s.selected=null;s.overrides={};s.noImage=true;s.checked=true;s.warnings=true;if(previous)s.previousDesign=previous;dirty();}save();}catch(e){if(token!==job||s!==target)return;if(kind==='analyze')Ref.ensure(s).analysis={status:'failed',kind:'codex'};error=e.name==='AbortError'?'AI调用已取消，原图和商品已保留。':e.message==='Failed to fetch'?'无法连接本机Codex服务，请确认59319端口服务已启动。':e.message;save();}finally{if(token===job){busy=null;aiController=null;render();document.querySelector('.main')?.scrollTo(0,0);}}}
act=async function(a,id){if(a==='about'){modal('静态电子菜单 · 本机AI试验版','<p>用途规格 → 选择模板 → 选择商品 → 成品与导出。</p><p>上传参考图需先确认发送并通过真实 Codex 分析。生成时 AI 提供配色与布局，程序绑定商品资料。支持图片和栅格 PDF 导出，不包含点餐、支付或设备发布。</p><p>本机 CLI 试验接入，非生产服务；复杂装饰及字体不能逐像素复刻。</p>');return;}if(a==='ai-dismiss'){aiPending=null;close();return;}if(a==='ai-start'){const p=aiPending;aiPending=null;close();if(p&&!busy)await aiRun(p);return;}if(a==='cancel-job'&&busy?.type?.startsWith('codex')){job++;aiController?.abort();aiController=null;if(busy.type==='codex-analysis')Ref.ensure(s).analysis={status:'cancelled',kind:'codex'};busy=null;error='已取消AI调用，参考图与商品已保留。已发出的请求仍可能计入额度。';save();render();return;}if(!busy&&(a==='ref-analyze'||a==='simple-generate'||a==='generate')){aiConfirm(a==='ref-analyze'?'analyze':'generate');return;}await aiPreviousAct(a,id);};
dirty=function(regenerate=false){if(regenerate)delete s.aiDesign;aiPreviousDirty(regenerate);};
simpleTemplateReady=function(){const r=Ref.ensure(s);return !!r.source&&r.analysis.status==='ready'&&(r.source==='gallery'||r.analysis.kind==='codex');};
simpleSetCapacity=function(){s.density=s.aiDesign?.capacity||Ref.ensure(s).analysis?.result?.capacity||simpleCapacity[Ref.ensure(s).recipe]||4;};
loading=function(){if(!busy?.type?.startsWith('codex'))return aiPreviousLoading();return `<section class="section" role="status" aria-live="polite"><span class="badge">真实 Codex 调用</span><h2>${busy.type==='codex-analysis'?'正在分析参考图':'正在设计菜单布局'}</h2><p>等待本机 Codex 返回结构化结果。未伪造进度百分比；可能需要 1–3 分钟。</p><p class="hint">仅在返回成功且配色、布局通过安全检查后采用。</p>${btn('取消，保留草稿','cancel-job')}</section>`;};
simpleUploadAnalysisView=function(){const r=Ref.ensure(s);if(r.source!=='upload')return '';const ready=r.analysis.status==='ready'&&r.analysis.kind==='codex',v=ready?r.analysis.result:null;return `<section class="section simple-upload-analysis"><div class="section-head"><div><h2>分析你的参考图</h2><p class="hint">上传参考图 → 真实AI分析 → 选择商品</p></div><span class="badge ${ready?'good':'warn'}">${ready?'Codex 分析完成':r.analysis.status==='failed'?'分析失败':r.analysis.status==='cancelled'?'已取消':'待真实分析'}</span></div><div class="row"><img class="simple-upload" src="${E(r.image)}" alt="已上传参考图"><div><h3>${E(r.name)}</h3><p>点击后确认发送范围，再通过本机 Codex 分析图片。</p>${btn('更换参考图','ref-upload','','sm')}${btn(ready?'重新分析参考图':'分析参考图','ref-analyze','','primary')}</div></div>${v?`<div class="analysis-report"><h3>风格分析结果 · ${E(v.styleName)}</h3><p>${E(v.summary)}</p><dl class="analysis-facts"><div><dt>配色</dt><dd><span class="analysis-swatches">${Object.values(v.palette).map(c=>`<span style="background:${c}" title="${c}"></span>`).join('')}</span>${E(v.palette.bg)} / ${E(v.palette.ink)} / ${E(v.palette.accent)}</dd></div>${[['composition','构图'],['typography','字体'],['decoration','装饰']].map(([k,n])=>`<div><dt>${n}</dt><dd>${E(v[k])}</dd></div>`).join('')}</dl><p class="hint">建议每页 ${v.capacity} 道 · 实际生成将结合所选商品适配 · ${E(r.analysis.completedAt||'')}</p></div>`:'<p class="hint">历史模拟结果不会作为真实AI分析结果使用。分析失败可重试，不会伪造报告。</p>'}</section>`;};
simpleBrief=function(){return aiPreviousBrief().replace('生成与上传参考图分析均为本地模拟，尚未接入真实 AI。图片 / PDF 可以实际导出。','已接入本机 Codex。点击分析或生成后需确认发送资料；将使用当前登录账户额度。图片 / PDF 可导出。');};
const aiPreviousHome=homeView;homeView=function(){return aiPreviousHome().replace('这是设计确认原型。','这是独立菜单设计工作台。').replace('生成过程采用本地规则演示，未接入 AI 或餐厅业务数据。','通过本机 Codex 分析参考图和设计布局；每次发送资料前需确认。未连接餐厅业务系统。');};
const aiPreviousHeader=header;header=function(){return aiPreviousHeader().replace(/交互原型 v0\.4|交互原型 v0\.5 · 精简版/,'独立工作台 · 本机 AI').replace('原型说明','工作台说明');};
const aiPreviousEditor=editor;editor=function(){return aiPreviousEditor().replace('重生成当前页','本页规则重排');};
render();
